const { test, expect } = await import(process.env.BW_PLAYWRIGHT_TEST);

test("AC-014 the output shows 5, with a message", async ({ page }) => {
  await page.goto("index.html");
  await expect(page.locator("#out"), "the output").toHaveText("5");
});

